{"command": "cd /root/.openclaw/workspace-agents/minimal && python3 -c "
import json
# Read posts.jsonl and check public_series_name for each post
series_map = {}
with open('bilibili-514527835-20260728/source/posts.jsonl') as f:
    for line in f:
        post = json.loads(line)
        pid = post['post_id']
        psn = post.get('platform_metrics',{}).get('series_name')
        if psn:
            series_map[pid] = psn
print('Posts with non-null series_name:', series_map)
# Also check is_original
orig_map = {}
with open('bilibili-514527835-20260728/source/posts.jsonl') as f:
    for line in f:
        post = json.loads(line)
        pid = post['post_id']
        iso = post.get('is_repost')
        if iso is not None:
            orig_map[pid] = iso
print('Posts with non-null is_repost (is_original must match):', orig_map)
""}

{"command": "cd /root/.openclaw/workspace-agents/minimal && python3 -c "
import json
posts = []
with open('bilibili-514527835-20260728/source/posts.jsonl') as f:
    for line in f:
        posts.append(json.loads(line))

# Check first 5 posts is_repost
for p in posts[:5]:
    print(p['post_id'], 'is_repost:', p.get('is_repost'))
""}

{"command": "python3 -c "
import json
with open('/root/.openclaw/workspace-agents/minimal/bilibili-514527835-20260728/source/posts.jsonl') as f:
    for line in f:
        p = json.loads(line)
        if p['post_id'] == 'BV16bLE6FEh1':
            print(json.dumps(p, ensure_ascii=False, indent=2))
            break
""}

